package net.civeira.phylax.feature.observe.observedsource.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observedsource.domain.ObservedSource;
import net.civeira.phylax.feature.observe.observedsource.domain.valueobject.TraceSampleRateVO;

class TraceSampleRateValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of trace sample rate of observed source")
  void test_trace_sample_rate_value_holder_assign_plain_value() {
    Object holder = new Object();
    TraceSampleRateValueHolder<Object> value = new TraceSampleRateValueHolder<>(holder);
    Assertions.assertSame(holder, value.traceSampleRate(1), "Setters must return the holder");
    Assertions.assertTrue(value.getTraceSampleRateValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getTraceSampleRate().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.traceSampleRateNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getTraceSampleRateValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getTraceSampleRate().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of trace sample rate of observed source")
  void test_trace_sample_rate_value_holder_assign_value_object() {
    Object holder = new Object();
    TraceSampleRateValueHolder<Object> value = new TraceSampleRateValueHolder<>(holder);
    TraceSampleRateVO vo = TraceSampleRateVO.from(1);
    Assertions.assertFalse(value.getTraceSampleRateValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.traceSampleRate(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getTraceSampleRateValue().orElseThrow());
    Assertions.assertSame(holder, value.traceSampleRate(Optional.empty()));
    Assertions.assertFalse(value.getTraceSampleRateValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.traceSampleRate(Optional.of(vo)));
    Assertions.assertSame(vo, value.getTraceSampleRateValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of trace sample rate of observed source against the original")
  void test_trace_sample_rate_value_holder_read() {
    Object holder = new Object();
    TraceSampleRateValueHolder<Object> value = new TraceSampleRateValueHolder<>(holder);
    TraceSampleRateVO vo = TraceSampleRateVO.from(1);
    TraceSampleRateVO other = TraceSampleRateVO.from(1);
    ObservedSource original = Mockito.mock(ObservedSource.class);
    Mockito.when(original.getTraceSampleRateValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readTraceSampleRate(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readTraceSampleRate(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.traceSampleRate(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readTraceSampleRate(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readTraceSampleRate(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of trace sample rate of observed source")
  void test_trace_sample_rate_value_holder_unset() {
    Object holder = new Object();
    TraceSampleRateValueHolder<Object> value = new TraceSampleRateValueHolder<>(holder);
    TraceSampleRateVO vo = TraceSampleRateVO.from(1);
    value.traceSampleRate(vo);
    Assertions.assertSame(holder, value.unsetTraceSampleRateIfMatches("traceSampleRate_other"));
    Assertions.assertTrue(value.getTraceSampleRateValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetTraceSampleRateIfMatches("traceSampleRate"));
    Assertions.assertFalse(value.getTraceSampleRateValue().isPresent(),
        "The field name must clear the value");
    value.traceSampleRate(vo);
    Assertions.assertSame(holder, value.unsetTraceSampleRate());
    Assertions.assertFalse(value.getTraceSampleRateValue().isPresent(),
        "Unset must clear the value");
  }
}
